package main

import (
	"context"
	"log/slog"
	"testing"

	"github.com/debpalash/OpenGTM/apps/backend-go/internal/config"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/runplan"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/vendorcatalog"
)

type emptySecrets struct{}

func (emptySecrets) Get(context.Context, string, string) (string, string, error) { return "", "", nil }

// TestWorkerProviderRunnerServesManifestProviders (final review C2): the worker's provider runner
// executes the built-in declarative providers (no Go implementation), so the default mobile_phone
// waterfall and every providerrun caller can run them; an unknown name stays unavailable. The
// worker also wires the vendor catalog to the connector index, so a refresh it plans prices a
// connector by its declared cost_per_lookup like the API does.
func TestWorkerProviderRunnerServesManifestProviders(t *testing.T) {
	runplan.ResetWiredForTest()
	t.Cleanup(runplan.ResetWiredForTest)
	r := workerProviderRunner(config.Config{AppEnv: "test"}, nil, emptySecrets{}, nil, slog.Default())
	for _, name := range []string{"leadmagic_mobile", "prospeo_mobile", "leadmagic_email", "leadmagic_company", "hunter_io"} {
		if !r.Serves(name) {
			t.Errorf("worker runner does not serve %s", name)
		}
	}
	if r.Serves("no_such_vendor") {
		t.Error("unknown provider served")
	}
	if !runplan.Wired() {
		t.Fatal("the worker did not wire the vendor catalog to the connector index")
	}
	if !vendorcatalog.HasKnownCost("leadmagic_company") {
		t.Error("declared manifest cost unknown in the worker")
	}
}

package main

import (
	"strings"
	"testing"
)

// R-secret: the worker refuses to start without a strong SECRET_KEY unless APP_ENV=test, before it touches the database.
func TestRunRefusesWeakSecretKey(t *testing.T) {
	for _, tc := range []struct{ env, key string }{{"production", ""}, {"dev", ""}, {"dev", "short"}, {"", ""}, {"local", "short"}} {
		t.Setenv("DATABASE_URL", "postgres://u:pw@127.0.0.1:1/d")
		t.Setenv("INTERNAL_SERVICE_TOKEN", strings.Repeat("t", 40))
		t.Setenv("OUTREACH_PUBLIC_BASE_URL", "https://outreach.example.com") // required outside dev since the cutover
		t.Setenv("APP_ENV", tc.env)
		t.Setenv("SECRET_KEY", tc.key)
		err := run()
		if err == nil || !strings.Contains(err.Error(), "SECRET_KEY") {
			t.Fatalf("APP_ENV=%q key=%q: want SECRET_KEY refusal, got %v", tc.env, tc.key, err)
		}
	}
}

//go:build integration

package api

import (
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"

	"github.com/debpalash/OpenGTM/apps/backend-go/internal/httpx"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/identity"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/testpg"
)

func newLimitedAuthEnv(t *testing.T) env {
	t.Helper()
	pool := testpg.NewAppPool(t, 4)
	st := identity.NewStore(pool)
	r := httpx.NewRouter()
	RegisterAuth(r, Deps{Pool: pool, Signer: testSigner, Identity: st, Limiter: frozenLimiter()})
	return env{h: r.Handler(), st: st}
}

func postFrom(e env, path, ctype, body, remote string) *httptest.ResponseRecorder {
	req := httptest.NewRequest("POST", path, strings.NewReader(body))
	req.Header.Set("Content-Type", ctype)
	req.RemoteAddr = remote
	rec := httptest.NewRecorder()
	e.h.ServeHTTP(rec, req)
	return rec
}

func want429(t *testing.T, rec *httptest.ResponseRecorder, what string) {
	t.Helper()
	if rec.Code != 429 {
		t.Fatalf("%s: want 429, got %d %s", what, rec.Code, rec.Body.String())
	}
	if s, err := strconv.Atoi(rec.Header().Get("Retry-After")); err != nil || s < 1 {
		t.Fatalf("%s: Retry-After %q", what, rec.Header().Get("Retry-After"))
	}
}

// Final security M2: online password guessing is throttled per username, whatever IP it comes from.
func TestTokenRateLimitedPerUsername(t *testing.T) {
	e := newLimitedAuthEnv(t)
	e.seedPW(t, "rl-victim", "right-password-123", true)
	body := form("username", "rl-victim", "password", "wrong")
	for i := 0; i < tokenUserBurst; i++ {
		remote := "203.0.113." + strconv.Itoa(i+1) + ":1234"
		if rec := postFrom(e, "/auth/token", formCT, body, remote); rec.Code != 401 {
			t.Fatalf("attempt %d: want 401, got %d", i, rec.Code)
		}
	}
	// A fresh IP, same username (case/space variants included), even with the right password: refused before bcrypt.
	want429(t, postFrom(e, "/auth/token", formCT, form("username", " RL-Victim ", "password", "right-password-123"), "198.51.100.9:1"), "per-username")
	// Another username is unaffected.
	e.seedPW(t, "rl-other", "right-password-123", true)
	if rec := postFrom(e, "/auth/token", formCT, form("username", "rl-other", "password", "right-password-123"), "198.51.100.9:1"); rec.Code != 200 {
		t.Fatalf("other user: %d", rec.Code)
	}
}

// Final security M2: one client IP cannot spray many usernames.
func TestTokenRateLimitedPerIP(t *testing.T) {
	e := newLimitedAuthEnv(t)
	for i := 0; i < tokenIPBurst; i++ {
		body := form("username", "nobody-"+strconv.Itoa(i), "password", "x")
		if rec := postFrom(e, "/auth/token", formCT, body, "192.0.2.7:5555"); rec.Code != 401 {
			t.Fatalf("attempt %d: want 401, got %d", i, rec.Code)
		}
	}
	want429(t, postFrom(e, "/auth/token", formCT, form("username", "nobody-x", "password", "x"), "192.0.2.7:5555"), "per-ip")
	if rec := postFrom(e, "/auth/token", formCT, form("username", "nobody-y", "password", "x"), "192.0.2.8:5555"); rec.Code != 401 {
		t.Fatalf("other IP: %d", rec.Code)
	}
}

// Final security M2: /auth/refresh is throttled per client IP.
func TestRefreshRateLimitedPerIP(t *testing.T) {
	e := newLimitedAuthEnv(t)
	for i := 0; i < refreshIPBurst; i++ {
		if rec := postFrom(e, "/auth/refresh", "application/json", `{"refresh_token":"bogus"}`, "192.0.2.9:1"); rec.Code != 401 {
			t.Fatalf("attempt %d: want 401, got %d", i, rec.Code)
		}
	}
	want429(t, postFrom(e, "/auth/refresh", "application/json", `{"refresh_token":"bogus"}`, "192.0.2.9:1"), "refresh")
}

//go:build integration

package api

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"testing"
	"time"

	"github.com/debpalash/OpenGTM/apps/backend-go/internal/auth"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/contract"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/httpx"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/identity"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/testpg"
)

var testSigner = auth.Signer{Secret: []byte("test-only-secret"), AccessTTL: time.Hour, RefreshTTL: 2 * time.Hour}

// pythonHash is bcrypt.hashpw(b"py-hash-pass") from Python's bcrypt ($2b$).
const pythonHash = "$2b$04$evf/l9TLJnVNly5eNvqVguqpHwFukwqC6CCZ2uDaJZDaRxNaw3o2a"

type env struct {
	h  http.Handler
	st *identity.Store
}

func newEnv(t *testing.T) env {
	t.Helper()
	pool := testpg.NewAppPool(t, 4)
	st := identity.NewStore(pool)
	r := httpx.NewRouter()
	RegisterAuth(r, Deps{Pool: pool, Signer: testSigner, Identity: st})
	return env{h: r.Handler(), st: st}
}

func (e env) seed(t *testing.T, name, hash string, active bool, role string, admin bool) {
	t.Helper()
	ctx := context.Background()
	if old, err := e.st.ByUsername(ctx, name); err == nil {
		_ = e.st.Delete(ctx, old.ID)
	}
	u, err := e.st.Insert(ctx, identity.NewUser{Username: name, HashedPassword: hash, IsActive: active, IsAdmin: admin, Role: role})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = e.st.Delete(context.Background(), u.ID) })
}

func (e env) seedPW(t *testing.T, name, pw string, active bool) {
	t.Helper()
	h, err := auth.HashPassword(pw)
	if err != nil {
		t.Fatal(err)
	}
	e.seed(t, name, h, active, "user", false)
}

func (e env) do(method, path, ctype, body string, hdr map[string]string) (*httptest.ResponseRecorder, contract.Resp) {
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	if ctype != "" {
		req.Header.Set("Content-Type", ctype)
	}
	for k, v := range hdr {
		req.Header.Set(k, v)
	}
	rec := httptest.NewRecorder()
	e.h.ServeHTTP(rec, req)
	h := map[string]string{}
	for _, k := range []string{"Content-Type", "WWW-Authenticate", "Allow"} {
		if v := rec.Header().Get(k); v != "" {
			h[k] = v
		}
	}
	return rec, contract.Resp{Status: rec.Code, Headers: h, Body: json.RawMessage(rec.Body.Bytes())}
}

func form(kv ...string) string {
	v := url.Values{}
	for i := 0; i < len(kv); i += 2 {
		v.Set(kv[i], kv[i+1])
	}
	return v.Encode()
}

const formCT = "application/x-www-form-urlencoded"

func (e env) login(t *testing.T, user, pw string) (access, refresh string) {
	t.Helper()
	rec, _ := e.do("POST", "/auth/token", formCT, form("username", user, "password", pw), nil)
	var b struct{ AccessToken, RefreshToken string }
	var m map[string]string
	if rec.Code != 200 || json.Unmarshal(rec.Body.Bytes(), &m) != nil {
		t.Fatalf("login: %d", rec.Code)
	}
	b.AccessToken, b.RefreshToken = m["access_token"], m["refresh_token"]
	return b.AccessToken, b.RefreshToken
}

func TestTokenSuccessMatchesFixture(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "alice", "alice-pass-1", true)
	fx := contract.Load(t, "auth/token_success")
	_, got := e.do("POST", "/auth/token", formCT, form("username", "alice", "password", "alice-pass-1"), nil)
	contract.AssertEqual(t, got, fx.Response, contract.IgnoreShapeOf("$.access_token", "$.refresh_token"))
	u, _ := e.st.ByUsername(context.Background(), "alice")
	if u.LastLogin == nil {
		t.Fatal("last_login not updated")
	}
}

func TestTokenBadPasswordMatchesFixture(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "alice", "alice-pass-1", true)
	fx := contract.Load(t, "auth/token_bad_password")
	_, got := e.do("POST", "/auth/token", formCT, form("username", "alice", "password", "wrong-password"), nil)
	contract.AssertEqual(t, got, fx.Response)
	_, got = e.do("POST", "/auth/token", formCT, form("username", "nobody-here", "password", "x"), nil)
	contract.AssertEqual(t, got, fx.Response)
}

func TestTokenMissingFieldIs422Fixture(t *testing.T) {
	e := newEnv(t)
	fx := contract.Load(t, "auth/token_missing_field")
	_, got := e.do("POST", "/auth/token", formCT, form("username", "alice"), nil)
	contract.AssertEqual(t, got, fx.Response)
	// FastAPI treats an empty required form value as missing.
	_, got = e.do("POST", "/auth/token", formCT, form("username", "alice", "password", ""), nil)
	contract.AssertEqual(t, got, fx.Response)
}

func TestTokenAcceptsPythonHash(t *testing.T) {
	e := newEnv(t)
	e.seed(t, "t9-pyhash", pythonHash, true, "user", false)
	rec, _ := e.do("POST", "/auth/token", formCT, form("username", "t9-pyhash", "password", "py-hash-pass"), nil)
	if rec.Code != 200 {
		t.Fatalf("got %d %s", rec.Code, rec.Body.String())
	}
}

func TestRefreshRoundTrip(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "t9-rt", "pw-1", true)
	_, refresh := e.login(t, "t9-rt", "pw-1")
	rec, _ := e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+refresh+`"}`, nil)
	if rec.Code != 200 {
		t.Fatalf("got %d %s", rec.Code, rec.Body.String())
	}
	var m map[string]string
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	if m["token_type"] != "bearer" || m["access_token"] == "" || m["refresh_token"] == "" {
		t.Fatalf("body %v", m)
	}
	c, err := testSigner.ParseAny(m["refresh_token"])
	if err != nil || c.Type != "refresh" || len(c.AMR) != 1 || c.AMR[0] != "pwd" {
		t.Fatalf("%+v %v", c, err)
	}
	if c, err = testSigner.ParseAccess(m["access_token"]); err != nil || c.Sub != "t9-rt" {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestRefreshRejectsAccessToken(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "t9-acc", "pw-1", true)
	access, _ := e.login(t, "t9-acc", "pw-1")
	fx := contract.Load(t, "auth/refresh_invalid")
	cases := map[string]string{"access": access, "garbage": "not-a-jwt"}
	nosub, _ := testSigner.Refresh("", nil)
	cases["empty-sub"] = nosub
	unknown, _ := testSigner.Refresh("t9-nobody", nil)
	cases["unknown-user"] = unknown
	for name, tok := range cases {
		_, got := e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+tok+`"}`, nil)
		t.Run(name, func(t *testing.T) { contract.AssertEqual(t, got, fx.Response) })
	}
}

func TestRefreshMissingFieldIs422Fixture(t *testing.T) {
	e := newEnv(t)
	fx := contract.Load(t, "auth/refresh_missing_field")
	_, got := e.do("POST", "/auth/refresh", "application/json", `{}`, nil)
	contract.AssertEqual(t, got, fx.Response)
}

func TestRefreshRejectsInactiveUser(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "t9-off", "pw-1", false)
	tok, _ := testSigner.Refresh("t9-off", []string{"pwd"})
	fx := contract.Load(t, "auth/refresh_invalid")
	_, got := e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+tok+`"}`, nil)
	contract.AssertEqual(t, got, fx.Response)
}

func TestRefreshKeepsSSOAmr(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "t9-sso", "pw-1", true)
	tok, _ := testSigner.Refresh("t9-sso", []string{"sso"})
	rec, _ := e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+tok+`"}`, nil)
	var m map[string]string
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	for _, k := range []string{"access_token", "refresh_token"} {
		c, err := testSigner.ParseAny(m[k])
		if err != nil || len(c.AMR) != 1 || c.AMR[0] != "sso" {
			t.Fatalf("%s: %+v %v", k, c, err)
		}
	}
	// no amr claim defaults to ["pwd"]
	tok, _ = testSigner.Refresh("t9-sso", nil)
	rec, _ = e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+tok+`"}`, nil)
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	if c, _ := testSigner.ParseAny(m["access_token"]); len(c.AMR) != 1 || c.AMR[0] != "pwd" {
		t.Fatalf("default amr: %+v", c)
	}
}

// Refresh keeps the workspace scope of an SSO session (sso_ws) on both new tokens; unscoped refresh
// tokens stay unscoped.
func TestRefreshKeepsSSOWorkspaceScope(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "t9-ssows", "pw-1", true)
	tok, _ := testSigner.RefreshFor("t9-ssows", []string{"sso"}, "ws-scope-1")
	rec, _ := e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+tok+`"}`, nil)
	var m map[string]string
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	for _, k := range []string{"access_token", "refresh_token"} {
		c, err := testSigner.ParseAny(m[k])
		if err != nil || c.Workspace != "ws-scope-1" || len(c.AMR) != 1 || c.AMR[0] != "sso" {
			t.Fatalf("%s: %d %+v %v", k, rec.Code, c, err)
		}
	}
	tok, _ = testSigner.Refresh("t9-ssows", []string{"pwd"})
	rec, _ = e.do("POST", "/auth/refresh", "application/json", `{"refresh_token":"`+tok+`"}`, nil)
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	for _, k := range []string{"access_token", "refresh_token"} {
		if c, err := testSigner.ParseAny(m[k]); err != nil || c.Workspace != "" {
			t.Fatalf("unscoped %s: %+v %v", k, c, err)
		}
	}
}

func TestMeMatchesFixture(t *testing.T) {
	e := newEnv(t)
	e.seed(t, "alice", pythonHash, true, "admin", true)
	tok, _ := testSigner.Access("alice", []string{"pwd"})
	fx := contract.Load(t, "auth/me_ok")
	_, got := e.do("GET", "/auth/me", "", "", map[string]string{"Authorization": "Bearer " + tok})
	contract.AssertEqual(t, got, fx.Response, contract.IgnorePaths("$.id", "$.last_login", "$.created_at"))
	fx = contract.Load(t, "auth/me_no_token")
	_, got = e.do("GET", "/auth/me", "", "", nil)
	contract.AssertEqual(t, got, fx.Response)
}

func TestTokenAndRefreshAreNotCacheable(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "alice", "alice-pass-1", true)
	rec, _ := e.do("POST", "/auth/token", formCT, form("username", "alice", "password", "alice-pass-1"), nil)
	var m map[string]string
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	for name, r := range map[string]*httptest.ResponseRecorder{"token": rec} {
		if r.Header().Get("Cache-Control") != "no-store" || r.Header().Get("Pragma") != "no-cache" {
			t.Errorf("%s: Cache-Control=%q Pragma=%q", name, r.Header().Get("Cache-Control"), r.Header().Get("Pragma"))
		}
	}
	rec, _ = e.do("POST", "/auth/refresh", "application/json", mustJSON(map[string]string{"refresh_token": m["refresh_token"]}), nil)
	if rec.Code != 200 || rec.Header().Get("Cache-Control") != "no-store" || rec.Header().Get("Pragma") != "no-cache" {
		t.Errorf("refresh: %d Cache-Control=%q Pragma=%q", rec.Code, rec.Header().Get("Cache-Control"), rec.Header().Get("Pragma"))
	}
}

func TestTokenEmptyHashRunsDummyVerify(t *testing.T) {
	e := newEnv(t)
	e.seed(t, "nohash", "", true, "user", false)
	calls := 0
	old := dummyVerify
	dummyVerify = func() { calls++ }
	defer func() { dummyVerify = old }()
	fx := contract.Load(t, "auth/token_bad_password")
	_, got := e.do("POST", "/auth/token", formCT, form("username", "nohash", "password", "whatever-1"), nil)
	contract.AssertEqual(t, got, fx.Response)
	if calls != 1 {
		t.Fatalf("DummyVerify calls for empty-hash user = %d, want 1", calls)
	}
	// unknown user also still burns one verify
	e.do("POST", "/auth/token", formCT, form("username", "ghost-user", "password", "x"), nil)
	if calls != 2 {
		t.Fatalf("DummyVerify calls after unknown user = %d, want 2", calls)
	}
}

// S-L22: an inactive user with the right password gets the bad-password 401 and no token.
func TestTokenRejectsInactiveUser(t *testing.T) {
	e := newEnv(t)
	e.seedPW(t, "t22-off", "off-pass-1", false)
	fx := contract.Load(t, "auth/token_bad_password")
	rec, got := e.do("POST", "/auth/token", formCT, form("username", "t22-off", "password", "off-pass-1"), nil)
	contract.AssertEqual(t, got, fx.Response)
	if strings.Contains(rec.Body.String(), "access_token") {
		t.Fatal("inactive user got a token")
	}
	u, _ := e.st.ByUsername(context.Background(), "t22-off")
	if u.LastLogin != nil {
		t.Fatal("inactive login touched last_login")
	}
}

package api

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/debpalash/OpenGTM/apps/backend-go/internal/config"
)

// The SSO OIDC client reaches a private-address IdP only when SSO_EGRESS_ALLOW_HOSTS names it;
// the general EGRESS_ALLOW_HOSTS (Deps.EgressAllowHosts) does not widen it and nothing is allowed
// by default.
func TestSSOHTTPClientEgressAllowHosts(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(200) }))
	defer srv.Close()
	hostPort := strings.TrimPrefix(srv.URL, "http://")

	get := func(d Deps) error {
		resp, err := ssoHTTPClient(d).Get(srv.URL)
		if err == nil {
			resp.Body.Close()
		}
		return err
	}
	if err := get(Deps{}); err == nil {
		t.Fatal("private IdP reached with no allow-list")
	}
	if err := get(Deps{EgressAllowHosts: []string{hostPort}}); err == nil {
		t.Fatal("EGRESS_ALLOW_HOSTS must not widen the SSO client")
	}
	var f config.Flags
	f.Governance.SSOEgressAllowHosts = " , other.internal, " + hostPort
	if err := get(Deps{Flags: f}); err != nil {
		t.Fatalf("SSO_EGRESS_ALLOW_HOSTS entry refused: %v", err)
	}
}

