func TestSSOInactiveMemberRefused(t *testing.T) {
	e := newSSOLoginEnv(t, false)
	if _, err := e.pool.Exec(context.Background(), `UPDATE users SET is_active=false WHERE id=$1`, e.ids["viewer2"]); err != nil {
