}

// Implicit first-login linking never reaches an account that matters outside this workspace: a
// member of any other workspace (above all an owner/admin there), a global admin, or the owner of
// any workspace. The workspace's IdP could otherwise mint a session that works elsewhere.
func TestSSONoImplicitLinkOfCrossWorkspaceAccounts(t *testing.T) {
	e := newSSOLoginEnv(t, true)
	ctx := context.Background()
	other := e.tag + "-other"
	third := e.tag + "-third"
	mk := func(name string, admin bool) int32 {
		var id int32
		if err := e.pool.QueryRow(ctx, `INSERT INTO users (username, hashed_password, is_active, is_admin, role) VALUES ($1,'x',true,$2,'user') RETURNING id`,
			name+"@"+e.tag+".test", admin).Scan(&id); err != nil {
			t.Fatal(err)
		}
		if _, err := e.pool.Exec(ctx, `INSERT INTO workspace_members (workspace_id,user_id,role,created_at) VALUES ($1,$2,'editor',1)`, e.ws, id); err != nil {
			t.Fatal(err)
		}
		return id
	}
	adminElsewhere := mk("adminelsewhere", false)
	memberElsewhere := mk("memberelsewhere", false)
	mk("gadmin", true)
	ownsThird := mk("ownsthird", false)
	for _, m := range []struct {
		uid  int32
		role string
	}{{adminElsewhere, "admin"}, {memberElsewhere, "viewer"}} {
		if _, err := e.pool.Exec(ctx, `INSERT INTO workspace_members (workspace_id,user_id,role,created_at) VALUES ($1,$2,$3,1)`, other, m.uid, m.role); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := e.pool.Exec(ctx, `INSERT INTO workspaces (id,name,slug,description,icon,owner_id,created_at,updated_at) VALUES ($1::text,$1::text,$1::text,'','',$2,1,1)`,
		third, ownsThird); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _, _ = e.pool.Exec(context.Background(), `DELETE FROM workspaces WHERE id=$1`, third) })
	for _, who := range []string{"adminelsewhere", "memberelsewhere", "gadmin", "ownsthird"} {
		frag := e.login(t, "sub-"+who, who+"@"+e.tag+".test", nil)
		if frag.Get("sso_access_token") != "" || frag.Get("sso_error") == "" {
			t.Errorf("%s: linked implicitly: %v", who, frag)
		}
	}
	if n := e.bindings(t); n != 0 {
		t.Fatalf("bindings %d", n)
	}
}

// R-redirect: with SSO enabled but no SSO_REDIRECT_BASE_URL, login and callback refuse with a
// clear error; the callback URL is never built from the Host header.
func TestSSOLoginRequiresRedirectBaseURL(t *testing.T) {
	e := newSSOLoginEnvBase(t, false, "")
	rec := e.get("/auth/sso/"+e.slug+"/login", nil)
	if rec.Code != 404 || strings.TrimSpace(rec.Body.String()) != `{"detail":"`+ssoRedirectBaseRequired+`"}` {
		t.Fatalf("login %d %s", rec.Code, rec.Body)
	}
	if loc := rec.Header().Get("Location"); loc != "" {
		t.Fatalf("redirected to %q", loc)
	}
	rec = e.get("/auth/sso/"+e.slug+"/callback?state=x&code=y", nil)
	if rec.Code != 303 || !strings.HasPrefix(rec.Header().Get("Location"), "/login#sso_error=") {
		t.Fatalf("callback %d %q", rec.Code, rec.Header().Get("Location"))
	}
}

package identity

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/debpalash/OpenGTM/apps/backend-go/internal/auth"
	"github.com/debpalash/OpenGTM/apps/backend-go/internal/contract"
)

var testSigner = auth.Signer{Secret: []byte("test-only-secret"), AccessTTL: time.Hour, RefreshTTL: time.Hour}

func ok200() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(200) })
}

func run(mw func(http.Handler) http.Handler, hdr string, ctxUser *User) *httptest.ResponseRecorder {
	req := httptest.NewRequest("GET", "/auth/me", nil)
	if hdr != "" {
		req.Header.Set("Authorization", hdr)
	}
	if ctxUser != nil {
		req = req.WithContext(WithPrincipal(req.Context(), Principal{User: *ctxUser}))
	}
	rec := httptest.NewRecorder()
	mw(ok200()).ServeHTTP(rec, req)
	return rec
}

func TestMissingBearerIs401WithWWWAuthenticate(t *testing.T) {
	fx := contract.Load(t, "auth/me_no_token")
	for _, h := range []string{"", "Basic abc", "Bearer", "Bearer "} {
		rec := run(Authenticate(testSigner, nil), h, nil)
		contract.AssertEqual(t, contract.Resp{
			Status:  rec.Code,
			Headers: map[string]string{"content-type": rec.Header().Get("Content-Type"), "www-authenticate": rec.Header().Get("WWW-Authenticate")},
			Body:    json.RawMessage(rec.Body.Bytes()),
		}, fx.Response)
	}
}

func TestBadTokenIs401(t *testing.T) {
	rec := run(Authenticate(testSigner, nil), "Bearer garbage", nil)
	if rec.Code != 401 || rec.Body.String() != `{"detail":"Could not validate credentials"}` || rec.Header().Get("WWW-Authenticate") != "Bearer" {
		t.Fatalf("got %d %s", rec.Code, rec.Body.String())
	}
}

func TestRefreshTokenOnAPIIs401(t *testing.T) {
	tok, _ := testSigner.Refresh("alice", nil)
	rec := run(Authenticate(testSigner, nil), "Bearer "+tok, nil)
	if rec.Code != 401 || rec.Body.String() != `{"detail":"Could not validate credentials"}` {
		t.Fatalf("got %d %s", rec.Code, rec.Body.String())
	}
}

func TestNonAdminIs403AdminGate(t *testing.T) {
	rec := run(RequireGlobalAdmin(), "", &User{Username: "bob", Role: "user"})
	if rec.Code != 403 || rec.Body.String() != `{"detail":"Not authorized"}` {
		t.Fatalf("got %d %s", rec.Code, rec.Body.String())
